package com.company.skillplatform.user.infrastructure.entity;
import com.company.skillplatform.common.infrastructure.entity.BaseJpaEntity;import jakarta.persistence.*;import java.time.Instant;import java.util.Objects;
@Entity @Table(name="org_team",uniqueConstraints=@UniqueConstraint(name="uk_org_team_external",columnNames={"provider","external_department_id"})) public class OrgTeamEntity extends BaseJpaEntity{
 @Column(nullable=false,length=32)private String provider;@Column(name="external_department_id",nullable=false,length=128)private String externalDepartmentId;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="parent_id")private OrgTeamEntity parent;@Column(name="team_name",nullable=false,length=255)private String teamName;@Column(nullable=false,length=32)private String status;@Column(name="last_synced_at")private Instant lastSyncedAt;@Column(name="last_seen_sync_run_id")private Long lastSeenSyncRunId;@Column(name="external_parent_department_id",length=128)private String externalParentDepartmentId;@Version@Column(name="version_no",nullable=false)private int versionNo;protected OrgTeamEntity(){}public OrgTeamEntity(String provider,String externalId,OrgTeamEntity parent,String name){this.provider=provider;externalDepartmentId=externalId;this.parent=parent;teamName=name;status="ACTIVE";}public String getProvider(){return provider;}public String getExternalDepartmentId(){return externalDepartmentId;}public OrgTeamEntity getParent(){return parent;}public String getTeamName(){return teamName;}public String getStatus(){return status;}public int getVersionNo(){return versionNo;}public Instant getLastSyncedAt(){return lastSyncedAt;}public Long getLastSeenSyncRunId(){return lastSeenSyncRunId;}public boolean syncIfChanged(String name,OrgTeamEntity parent,Instant now,Long runId){boolean changed=!Objects.equals(teamName,name)||!Objects.equals(this.parent,parent)||!"ACTIVE".equals(status)||!Objects.equals(lastSeenSyncRunId,runId);teamName=name;this.parent=parent;status="ACTIVE";lastSyncedAt=now;lastSeenSyncRunId=runId;return changed;}public void sync(String name,OrgTeamEntity parent,Instant now){syncIfChanged(name,parent,now,null);}public void deactivate(){status="INACTIVE";}}
